script:
frappe.ui.form.on('Sales Order', {
    customer: function(frm) {
        if (frm.doc.customer) {
            frappe.db.get_doc('Customer', frm.doc.customer).then(cust => {
                frm.set_value('custom_plate_no', cust.custom_plate_no || '');
                frm.set_value('custom_vin', cust.custom_vin || '');
                frm.set_value('custom_mileage_type', cust.custom_mileage_type || 'km');
                frm.set_value('custom_model', cust.custom_model || '');
                frm.set_value('custom_engine_no', cust.custom_engine_no || '');
                frm.set_value('custom_registration_type', cust.custom_registration_type || '');
                frm.set_value('custom_transmission', cust.custom_transmission || '');
                frm.set_value('custom_cylinders', cust.custom_cylinders || '');
                frm.set_value('custom_year_model', cust.custom_year_model || '');
                frm.set_value('custom_insurance_expiry', cust.custom_insurance_expiry || '');
                frm.set_value('custom_color', cust.custom_color || '');
            });
        }
    }
});
